import type { ReactNode } from "react";
import { cn } from "./utils";

export type DocumentLayoutProps = {
    properties: ReactNode;
    children: ReactNode;
    layout?: "stacked" | "split";
    label?: string;
    className?: string;
};

export function DocumentLayout({ properties, children, layout = "stacked", label = "문서 속성", className }: DocumentLayoutProps) {
    if (layout !== "stacked" && layout !== "split") throw new RangeError("Unsupported document layout.");
    return <div data-ui="document-layout" data-layout={layout} className={cn("@container min-w-0", className)}>
        <div className={cn("grid min-w-0 gap-6", layout === "split" && "@4xl:grid-cols-[minmax(12rem,16rem)_minmax(0,1fr)]")}>
            <aside aria-label={label} className="min-w-0">{properties}</aside>
            <div className="min-w-0">{children}</div>
        </div>
    </div>;
}
